<?php require '../config.php';admin();if($_SERVER['REQUEST_METHOD']!=='POST')exit;verify();$id=(int)$_POST['id'];$st=$_POST['status']??'open';$pr=$_POST['priority']??'normal';$r=trim($_POST['reply']??'');if(!in_array($st,['open','pending','solved','closed'],true)||!in_array($pr,['low','normal','high','urgent'],true))exit('Invalid');$q=db()->prepare("UPDATE tickets SET status=?,priority=?,agent_reply=? WHERE id=?");$q->execute([$st,$pr,$r,$id]);flash('Ticket updated successfully.');header("Location:view.php?id=$id");